  - intros t Ht p _. apply fire_1RB0LC_1LC0LA_1RD1LA_0RD1LC. exact Ht.
  - exact wit_1RB0LC_1LC0LA_1RD1LA_0RD1LC.
  - apply qcleb_QC_11. reflexivity.
