(** 1RB0LC_1LC0RB_1LD1LA_0RA1RB *)
(** 1RB0LC_1LC0RB_1LD1LA_0RA1RB -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LC_1LC0RB_1LD1LA_0RA1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S1 DR StB end.

(** Its mirror 1LB0RC_1RC0LB_1RD1RA_0LA1LB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LC_1LC0RB_1LD1LA_0RA1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DL StB
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DL StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_1LC0RB_1LD1LA_0RA1RB : list Instr := [(StA, S0); (StC, S1)].
Definition tmw_1RB0LC_1LC0RB_1LD1LA_0RA1RB : TM := tm_wrap_trs tmm_1RB0LC_1LC0RB_1LD1LA_0RA1RB pins_1RB0LC_1LC0RB_1LD1LA_0RA1RB.
