Lemma mirror_ok_1RB0LC_1LC0RB_1LD1LA_0RA1RB : mirror_tm tm_1RB0LC_1LC0RB_1LD1LA_0RA1RB = tmm_1RB0LC_1LC0RB_1LD1LA_0RA1RB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

