    apply (fireo_1RB0LC_1LC1LA_0RD1LA_1LC1RD [SWinR 2; SCycL 2 0; SWin 6; SCycR 2; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
