(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB0LC_1LC1RA_0RD1LA_1LC1RD : forall j, lift (cden [] [] j BB1_1RB0LC_1LC1RA_0RD1LA_1LC1RD) = lift (Cin (pow2 j)).
Proof.
