  - exact bootq_1RB0LC_1LC1RA_0RD1LA_1LC1RD.
  - intros p _. apply lap_1RB0LC_1LC1RA_0RD1LA_1LC1RD.
  - intros t Ht p _. apply fire_1RB0LC_1LC1RA_0RD1LA_1LC1RD. exact Ht.
  - exact wit_1RB0LC_1LC1RA_0RD1LA_1LC1RD.
  - apply qcleb_QC_11. reflexivity.
Qed.

Theorem qhtr_1RB0LC_1LC1RA_0RD1LA_1LC1RD : NonHalt tm_1RB0LC_1LC1RA_0RD1LA_1LC1RD /\ QHBoundTr 32779478 tm_1RB0LC_1LC1RA_0RD1LA_1LC1RD /\ QuasiHaltsTr tm_1RB0LC_1LC1RA_0RD1LA_1LC1RD.
