Lemma run_inner_1RB0LC_1LC1RB_0RB1LD_0RA0LC : srun tm false true chn_1RB0LC_1LC1RB_0RB1LD_0RA0LC AI0_1RB0LC_1LC1RB_0RB1LD_0RA0LC = Some (AI1_1RB0LC_1LC1RB_0RB1LD_0RA0LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0LC_1LC1RB_0RB1LD_0RA0LC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chb_1RB0LC_1LC1RB_0RB1LD_0RA0LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_boot_1RB0LC_1LC1RB_0RB1LD_0RA0LC : srun tm true true chb_1RB0LC_1LC1RB_0RB1LD_0RA0LC B0_1RB0LC_1LC1RB_0RB1LD_0RA0LC = Some (BB1_1RB0LC_1LC1RB_0RB1LD_0RA0LC, 4, 7).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0LC_1LC1RB_0RB1LD_0RA0LC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB0LC_1LC1RB_0RB1LD_0RA0LC : list lstep := [SWinR 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 5; SRotL 1; SFoldL 1].

Lemma run_exit_1RB0LC_1LC1RB_0RB1LD_0RA0LC : srun tm true true che_1RB0LC_1LC1RB_0RB1LD_0RA0LC BE0_1RB0LC_1LC1RB_0RB1LD_0RA0LC = Some (B1_1RB0LC_1LC1RB_0RB1LD_0RA0LC, 4, 13).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0LC_1LC1RB_0RB1LD_0RA0LC.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_1RB0LC_1LC1RB_0RB1LD_0RA0LC, cden, A0_1RB0LC_1LC1RB_0RB1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB0LC_1LC1RB_0RB1LD_0RA0LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_1RB0LC_1LC1RB_0RB1LD_0RA0LC, cden, A1_1RB0LC_1LC1RB_0RB1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 8). split; [lia|].
  rewrite (gsi_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0LC_1LC1RB_0RB1LD_0RA0LC A0_1RB0LC_1LC1RB_0RB1LD_0RA0LC A1_1RB0LC_1LC1RB_0RB1LD_0RA0LC 4 8
             run_int_1RB0LC_1LC1RB_0RB1LD_0RA0LC (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j q0 E).
Qed.

Lemma gso_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LC_1LC1RB_0RB1LD_0RA0LC.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_1RB0LC_1LC1RB_0RB1LD_0RA0LC, cden, B0_1RB0LC_1LC1RB_0RB1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LC1RB_0RB1LD_0RA0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LC_1LC1RB_0RB1LD_0RA0LC
             = (StC, (rep [S1;S0] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_1RB0LC_1LC1RB_0RB1LD_0RA0LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0LC_1LC1RB_0RB1LD_0RA0LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LC_1LC1RB_0RB1LD_0RA0LC. reflexivity.
Qed.

Lemma gsn_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB0LC_1LC1RB_0RB1LD_0RA0LC.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_1RB0LC_1LC1RB_0RB1LD_0RA0LC, cden, AI0_1RB0LC_1LC1RB_0RB1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB0LC_1LC1RB_0RB1LD_0RA0LC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_1RB0LC_1LC1RB_0RB1LD_0RA0LC, cden, AI1_1RB0LC_1LC1RB_0RB1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 8), (cden (Ip q0 ++ [S1]) [] i AI1_1RB0LC_1LC1RB_0RB1LD_0RA0LC).
  split; [lia|]. split; [| exact (gen_1RB0LC_1LC1RB_0RB1LD_0RA0LC v i q0 E)].
  rewrite (gsn_1RB0LC_1LC1RB_0RB1LD_0RA0LC v i q0 E).
  exact (srun_sound tm false true chn_1RB0LC_1LC1RB_0RB1LD_0RA0LC AI0_1RB0LC_1LC1RB_0RB1LD_0RA0LC AI1_1RB0LC_1LC1RB_0RB1LD_0RA0LC 4 8
           run_inner_1RB0LC_1LC1RB_0RB1LD_0RA0LC (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall j, lift (cden [] [] j BB1_1RB0LC_1LC1RB_0RB1LD_0RA0LC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_1LC1RB_0RB1LD_0RA0LC = (StB, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB0LC_1LC1RB_0RB1LD_0RA0LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB0LC_1LC1RB_0RB1LD_0RA0LC. rewrite epow2_1RB0LC_1LC1RB_0RB1LD_0RA0LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LC_1LC1RB_0RB1LD_0RA0LC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LC_1LC1RB_0RB1LD_0RA0LC.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LC_1LC1RB_0RB1LD_0RA0LC, cden, BE0_1RB0LC_1LC1RB_0RB1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LC_1LC1RB_0RB1LD_0RA0LC p (pow2 j)).
  - exists (4 * j + 7), (cden [] [] j BB1_1RB0LC_1LC1RB_0RB1LD_0RA0LC).
    split; [lia|]. split; [| exact (gbo_1RB0LC_1LC1RB_0RB1LD_0RA0LC j)].
    rewrite (gso_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j E).
    exact (srun_sound tm true true chb_1RB0LC_1LC1RB_0RB1LD_0RA0LC B0_1RB0LC_1LC1RB_0RB1LD_0RA0LC BB1_1RB0LC_1LC1RB_0RB1LD_0RA0LC 4 7
             run_boot_1RB0LC_1LC1RB_0RB1LD_0RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 13), (cden [] [] j B1_1RB0LC_1LC1RB_0RB1LD_0RA0LC).
    split; [| exact (geo_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j E)].
    rewrite (gxi_1RB0LC_1LC1RB_0RB1LD_0RA0LC j).
    exact (srun_sound tm true true che_1RB0LC_1LC1RB_0RB1LD_0RA0LC BE0_1RB0LC_1LC1RB_0RB1LD_0RA0LC B1_1RB0LC_1LC1RB_0RB1LD_0RA0LC 4 13
             run_exit_1RB0LC_1LC1RB_0RB1LD_0RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0LC_1LC1RB_0RB1LD_0RA0LC : stepn tmm_1RB0LC_1LC1RB_0RB1LD_0RA0LC 7 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0LC_1LC1RB_0RB1LD_0RA0LC 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0LC_1LC1RB_0RB1LD_0RA0LC 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0LC_1LC1RB_0RB1LD_0RA0LC : existsb (fun tg => cfires tmm_1RB0LC_1LC1RB_0RB1LD_0RA0LC c0 7 tg) pins_1RB0LC_1LC1RB_0RB1LD_0RA0LC = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1LC1RB_0RB1LD_0RA0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j E)].
Qed.

(** A state that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.vis_via_int_lift] carries it to every anchor. *)
Lemma visi_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB0LC_1LC1RB_0RB1LD_0RA0LC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j q0 E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB0LC_1LC1RB_0RB1LD_0RA0LC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB0LC_1LC1RB_0RB1LD_0RA0LC p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_1LC1RB_0RB1LD_0RA0LC : forall t, ~ In t pins_1RB0LC_1LC1RB_0RB1LD_0RA0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_1LC1RB_0RB1LD_0RA0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB0LC_1LC1RB_0RB1LD_0RA0LC (StA, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB0LC_1LC1RB_0RB1LD_0RA0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LC_1LC1RB_0RB1LD_0RA0LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LC_1LC1RB_0RB1LD_0RA0LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LC_1LC1RB_0RB1LD_0RA0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LC_1LC1RB_0RB1LD_0RA0LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* D0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB0LC_1LC1RB_0RB1LD_0RA0LC (StD, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB0LC_1LC1RB_0RB1LD_0RA0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LC_1LC1RB_0RB1LD_0RA0LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
