  exists (4 * j + 8), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB0LC_1RC1LA_0RD1LA_1LC1RD).
  split; [lia|]. split; [| exact (gei_1RB0LC_1RC1LA_0RD1LA_1LC1RD p j q0 E)].
  rewrite (gsi_1RB0LC_1RC1LA_0RD1LA_1LC1RD p j q0 E).
  exact (srun_sound tm false true chi_1RB0LC_1RC1LA_0RD1LA_1LC1RD A0_1RB0LC_1RC1LA_0RD1LA_1LC1RD A1_1RB0LC_1RC1LA_0RD1LA_1LC1RD 4 8
           run_int_1RB0LC_1RC1LA_0RD1LA_1LC1RD (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB0LC_1RC1LA_0RD1LA_1LC1RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LC_1RC1LA_0RD1LA_1LC1RD.
Proof.
