Proof.
  assert (H : match csteps tmm_1RB0LC_1RC1LA_0RD1LA_1LC1RD 14 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0LC_1RC1LA_0RD1LA_1LC1RD 14 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0LC_1RC1LA_0RD1LA_1LC1RD : existsb (fun tg => cfires tmm_1RB0LC_1RC1LA_0RD1LA_1LC1RD c0 14 tg) pins_1RB0LC_1RC1LA_0RD1LA_1LC1RD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_1RC1LA_0RD1LA_1LC1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1RC1LA_0RD1LA_1LC1RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_1RC1LA_0RD1LA_1LC1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1RC1LA_0RD1LA_1LC1RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_1RC1LA_0RD1LA_1LC1RD : forall t, ~ In t pins_1RB0LC_1RC1LA_0RD1LA_1LC1RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_1RC1LA_0RD1LA_1LC1RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1RC1LA_0RD1LA_1LC1RD [SWinR 2; SCycL 2 0; SWin 6; SCycR 2; SWin 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1RC1LA_0RD1LA_1LC1RD [SWinR 2; SCycL 2 0; SWin 5] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1RC1LA_0RD1LA_1LC1RD [SWinR 2; SCycL 2 0; SWin 6; SCycR 2; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1RC1LA_0RD1LA_1LC1RD [SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1RC1LA_0RD1LA_1LC1RD [SWinR 2; SCycL 2 0; SWin 4] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1RC1LA_0RD1LA_1LC1RD [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1RC1LA_0RD1LA_1LC1RD [SWinR 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtrm_1RB0LC_1RC1LA_0RD1LA_1LC1RD : NonHalt tmm_1RB0LC_1RC1LA_0RD1LA_1LC1RD /\ QHBoundTr 32779478 tmm_1RB0LC_1RC1LA_0RD1LA_1LC1RD /\ QuasiHaltsTr tmm_1RB0LC_1RC1LA_0RD1LA_1LC1RD.
Proof.
  apply (lap_qh_stage tmm_1RB0LC_1RC1LA_0RD1LA_1LC1RD pins_1RB0LC_1RC1LA_0RD1LA_1LC1RD Cc 2 14 32779478).
  - exact bootq_1RB0LC_1RC1LA_0RD1LA_1LC1RD.
  - intros p _. apply lap_1RB0LC_1RC1LA_0RD1LA_1LC1RD.
  - intros t Ht p _. apply fire_1RB0LC_1RC1LA_0RD1LA_1LC1RD. exact Ht.
  - exact wit_1RB0LC_1RC1LA_0RD1LA_1LC1RD.
  - apply qcleb_QC_11. reflexivity.
Qed.

Theorem qhtr_1RB0LC_1RC1LA_0RD1LA_1LC1RD : NonHalt tm_1RB0LC_1RC1LA_0RD1LA_1LC1RD /\ QHBoundTr 32779478 tm_1RB0LC_1RC1LA_0RD1LA_1LC1RD /\ QuasiHaltsTr tm_1RB0LC_1RC1LA_0RD1LA_1LC1RD.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0LC_1RC1LA_0RD1LA_1LC1RD). rewrite mirror_ok_1RB0LC_1RC1LA_0RD1LA_1LC1RD. exact qhtrm_1RB0LC_1RC1LA_0RD1LA_1LC1RD. Qed.

