  apply (fire_via_fill tm Cc Cin lapin_1RB0LC_1RC1RA_0RD1LA_1LC1RD t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB0LC_1RC1RA_0RD1LA_1LC1RD). split;
      [| exact (gbo_1RB0LC_1RC1RA_0RD1LA_1LC1RD j)].
    rewrite (gso_1RB0LC_1RC1RA_0RD1LA_1LC1RD p j E).
    exact (srun_sound tm true true chb_1RB0LC_1RC1RA_0RD1LA_1LC1RD B0_1RB0LC_1RC1RA_0RD1LA_1LC1RD BB1_1RB0LC_1RC1RA_0RD1LA_1LC1RD 4 8
             run_boot_1RB0LC_1RC1RA_0RD1LA_1LC1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LC_1RC1RA_0RD1LA_1LC1RD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LC_1RC1RA_0RD1LA_1LC1RD j)].
