    intros p1 j1 E1.
    exact (firex_1RB0LC_1RC1RA_0RD1LA_1LC1RD [SWinR 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
